<div class="agenda-panel-complemento"><h3>Registrar o actualizar día</h3><p>Si la fecha ya existe en el ciclo, se actualizará su clasificación.</p><form method="POST" action="{{ route('direccion.agenda.calendario-escolar.store') }}" class="agenda-fila-filtros">@csrf<input type="hidden" name="ciclo_escolar_id" value="{{ $cicloId }}"><label>Fecha<input type="date" name="fecha" class="form-control" value="{{ old('fecha') }}" required></label><label>Clasificación<select name="tipo" class="form-select" required>@foreach(['LECTIVO'=>'Lectivo','FERIADO'=>'Feriado','ASUETO'=>'Asueto','SUSPENSION'=>'Suspensión','OTRO'=>'Otro'] as $valor=>$texto)<option value="{{ $valor }}">{{ $texto }}</option>@endforeach</select></label><label>Descripción<input name="descripcion" maxlength="255" class="form-control" placeholder="Motivo o detalle" value="{{ old('descripcion') }}"></label><button class="btn btn-primary" type="submit">Guardar día</button></form></div>
<div class="agenda-panel-complemento"><h3>Días registrados <span class="agenda-contador">{{ $dias->count() }}</span></h3><div class="table-responsive"><table class="table"><thead><tr><th>Fecha</th><th>Tipo</th><th>Descripción</th><th>Acción</th></tr></thead><tbody>@forelse($dias as $dia)<tr><td>{{ $dia->fecha->format('d/m/Y') }}</td><td><span class="atlas-tag">{{ ucfirst(strtolower($dia->tipo)) }}</span></td><td>{{ $dia->descripcion ?: '—' }}</td><td><form method="POST" action="{{ route('direccion.agenda.calendario-escolar.destroy', $dia) }}" class="agenda-form-eliminar">@csrf @method('DELETE')<button type="button" class="btn btn-outline-danger btn-sm agenda-solicitar-eliminar" data-fecha="{{ $dia->fecha->format('d/m/Y') }}">Eliminar</button></form></td></tr>@empty<tr><td colspan="4">No hay fechas registradas.</td></tr>@endforelse</tbody></table></div></div>
<div class="atlas-modal" id="modalEliminarDia" hidden role="dialog" aria-modal="true" aria-labelledby="tituloEliminarDia"><div class="atlas-modal__panel"><div class="atlas-modal__header"><h4 id="tituloEliminarDia">Eliminar fecha del calendario</h4><button class="atlas-modal__close" type="button" data-cerrar-dia>&times;</button></div><div class="atlas-modal__body"><p id="textoEliminarDia"></p></div><div class="atlas-modal__footer"><button class="btn btn-outline-secondary" type="button" data-cerrar-dia>Volver</button><button class="btn btn-danger" id="confirmarEliminarDia" type="button">Eliminar fecha</button></div></div></div>
</div>
<script>document.addEventListener('DOMContentLoaded',()=>{const m=document.getElementById('modalEliminarDia');let form=null;const cerrar=()=>{m.hidden=true;form=null};document.querySelectorAll('.agenda-solicitar-eliminar').forEach(b=>b.addEventListener('click',()=>{form=b.closest('form');document.getElementById('textoEliminarDia').textContent='¿Eliminar el registro del '+b.dataset.fecha+'? Esta acción no elimina las actividades de la agenda.';m.hidden=false}));document.querySelectorAll('[data-cerrar-dia]').forEach(b=>b.addEventListener('click',cerrar));m.addEventListener('click',e=>{if(e.target===m)cerrar()});document.getElementById('confirmarEliminarDia').addEventListener('click',()=>{if(form)form.submit()});document.addEventListener('keydown',e=>{if(e.key==='Escape')cerrar()})})</script>
